#!/bin/bash
# نشر الـ19 عقد الجديدة بتاعة EVA من Termux
# الخطوات:
# 1) عدّل قيم الـ CONFIG اللي مكتوب عليها [املأ] تحت
# 2) قبل التشغيل:  export PK=0x....  (مفتاحك - مايتكتبش في الملف)
# 3) نفّذ:  bash deploy-19.sh   (أو سطر بسطر)
# 4) بعد ما تخلص:  unset PK && history -c
# ملحوظة: النشر ده بقرارك بعد كسر بوابة الـ SolidityScan - على مسؤوليتك

export RPC=https://mainnet.base.org
if [ -z "$PK" ]; then echo "حط مفتاحك الأول: export PK=0x..."; exit 1; fi

# ---------------- CONFIG ----------------
WALLET=0xE9B0CebeF9e93cAc7727A06D5ED5f8e3AE71e5F8   # محفظتك (تأكد إنه عنوان النشر)
CORE=0x0A834888B15d249f55498Dd16ac8a64B8c258396      # عقد التوكن الرسمي
H2=0x57025c9B3d2E691422EE9026f7eb2B582A2e0b51        # الـ Hub الجديد

# [املأ] نفس الأعضاء للحوكمة والخزانة (توصية المراجعة: نفس العناوين في كل حتة)
COUNCIL="[0xE9B0CebeF9e93cAc7727A06D5ED5f8e3AE71e5F8]"
REGISTRAR=$WALLET
MINTER=$WALLET

# [املأ] عناوين فيدز Chainlink على Base (الأول = نفس فيد الـ TWAP المنشور، اقراه من عقد TWAPOracleEngine)
FEED1=0x0000000000000000000000000000000000000000
FEED2=0x0000000000000000000000000000000000000000
FEED3=0x0000000000000000000000000000000000000000

# [املأ] ملاك المالتي سيج والعتبة
MSIG_OWNERS="[0xE9B0CebeF9e93cAc7727A06D5ED5f8e3AE71e5F8]"
MSIG_THRESHOLD=1

# [املأ] المستفيدين والنسب للمقسّم (مثال: عنوانين 50/50)
SPLIT_PAYEES="[0xE9B0CebeF9e93cAc7727A06D5ED5f8e3AE71e5F8]"
SPLIT_SHARES="[100]"

# روابط الـ NFT (تقدر تسيبها فاضية وتظبطها بعدين لو العقد يسمح، أو حط رابطك)
NFT_URI=""
LOYALTY_URI=""

# العتبات الدولارية: مثال - عدّل الأسماء والأهداف (بالدولار × 1e18) حسب رؤيتك
TH_N1=$(cast format-bytes32-string "EVA.USD.FLOOR")
TH_N2=$(cast format-bytes32-string "EVA.USD.CEIL")
TH_T1=1000000000000000000
TH_T2=100000000000000000000
# ---------------- END CONFIG ----------------

echo "=== 1/3 EVA_Treasury ==="""
ARGS=$(cast abi-encode "constructor(address[])" "$COUNCIL")
cast send --rpc-url $RPC --private-key $PK --create ${ARGS:2}
echo "^^ انسخ contractAddress"
echo ""
sleep 20
echo "=== 2/3 EVA_LoyaltyBadge ==="""
ARGS=$(cast abi-encode "constructor(address,address,string,uint256[4])" "$CORE" "$MINTER" "$LOYALTY_URI" "[1000000000000000000000,10000000000000000000000,100000000000000000000000,1000000000000000000000000]")
cast send --rpc-url $RPC --private-key $PK --create ${ARGS:2}
echo "^^ انسخ contractAddress"
echo ""
sleep 20
echo "=== 3/3 EVA_Subscriptions ==="""
cast send --rpc-url $RPC --private-key $PK --create 
echo "^^ انسخ contractAddress"
echo ""
sleep 20
